SystemErrorBatError;  /*Process Led open short detection*/			moduleLedUpdateStatus();	  /*Process temperature*/	     moduleTempUpdate();	  /*get current new LIN signal*/  /*Sometimes LIN control signal will update less then DSYSTEM_EVENT_LOOP_PERIOD, we need get update*/  /*LIN signal out side the main loop. Delete here*/  //systemLinCommSignalUpdate();  /*if new LIN signal received, try to power on and detect led for once*/  if ((sysStatus.errFlag & ESystemErrorLedError) &&      (sysStatus.newLinSignal == btrue))  {    moduleLedResetDetection();		Led_Error_flag = 0;  }}